

# This file was *autogenerated* from the file check_04_hermitian_and_c_plus.sage
from sage.all_cmdline import *   # import sage library

_sage_const_0 = Integer(0); _sage_const_2 = Integer(2); _sage_const_1 = Integer(1)# =========================================================================
# check_04: check_number_operator_is_hermitian / c_plus_equals_Lambda_half_integer
#   (1) Z_j^* = Z_j, Y_j^* = Y_j
#   (2) Ž_μ^* = Ž_{M+1−μ}, Y̌_μ^* = Y̌_{M+1−μ}
#   (3) (ψ̌_μ^†)^* = ψ̌_{M+1−μ}、および conj(α_μ) = −α_{M+1−μ}
#   (4) ň_μ^* = ň_μ, Q̌_ε^* = Q̌_ε
#   (5) V^{(+)} は実対称、W は実対称で成分がすべて正
#   (6) F^{(+)} 上で W = V^{(+)}
#   (7) c_+(M) = Λ̌_max = Λ^{(1/2)}_M
#       （c_+(M) は W を F^{(+)} ∩ R^{2^M} へ制限した Rayleigh 商の最大値として
#         直接求める。実基底 (e_k + e_{k̄})/‖·‖ を張って対称行列の最大固有値を取る。）
#   (8) 最大固有ベクトルは実に取れて F^{(+)} に属する
# =========================================================================
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '_prelude.sage'))

print("=== check_04: エルミート性と c_+(M) = Λ^{(1/2)}_M ===")

ok_all = True
w1 = w2 = w3 = w3a = w4 = w4q = _sage_const_0 
w_rs = w_pos = _sage_const_0 
w_WV = _sage_const_0 
w_cplus = _sage_const_0 
w_evec = _sage_const_0 


def flip_index(M, k):
    """基底番号 k（0 始まり、2 進で σ^z の符号）に対して全スピン反転した番号"""
    return (_sage_const_2  ** M - _sage_const_1 ) - k


def even_basis(M):
    """F^{(+)} ∩ R^{2^M} の正規直交基底（実）。(e_k + e_{k̄})/√2 を k < k̄ で取る。"""
    d = _sage_const_2  ** M
    cols = []
    for k in range(d):
        kb = flip_index(M, k)
        if k < kb:
            v = vector(RDF, d)
            v[k] = _sage_const_1  / sqrt(RDF(_sage_const_2 )); v[kb] = _sage_const_1  / sqrt(RDF(_sage_const_2 ))
            cols.append(v)
    return matrix(RDF, cols).transpose()


for M in EIG_M:
    O = SpinOps(M)
    E = eps_op(O)
    Id = identity_matrix(CDF, O.d)
    # (1)
    for j in range(_sage_const_1 , M + _sage_const_1 ):
        w1 = max(w1, herm_residual(O.Z[j]), herm_residual(O.Y[j]))
    Bplus = even_basis(M)
    for p in EIG_PARAMS:
        K1 = RDF(p['K1']); K2 = RDF(p['K2'])
        P = coeffs(K1, K2)
        ns = n_check_all(O, P)
        for mu in range(_sage_const_1 , M + _sage_const_1 ):
            nu = M + _sage_const_1  - mu
            # (2)
            w2 = max(w2, opnorm(checkZ(O, mu).conjugate_transpose() - checkZ(O, nu)))
            w2 = max(w2, opnorm(checkY(O, mu).conjugate_transpose() - checkY(O, nu)))
            # (3)
            pdag, _ = psi_pair(O, mu, P)
            _, psinu = psi_pair(O, nu, P)
            w3 = max(w3, opnorm(pdag.conjugate_transpose() - psinu))
            # (3a) conj(α_μ) = −α_{M+1−μ}
            a_mu = Pcheck(M, mu, P)[_sage_const_0 , _sage_const_0 ]
            a_nu = Pcheck(M, nu, P)[_sage_const_0 , _sage_const_0 ]
            w3a = max(w3a, abs(a_mu.conjugate() + a_nu))
            # (4)
            w4 = max(w4, herm_residual(ns[mu]))
        for e in eps_list(M):
            w4q = max(w4q, herm_residual(Q_check(O, e, ns)))
        # (5)
        Vp, _ = V_plus(O, K1, K2)
        W = W_op(O, K1, K2)
        w_rs = max(w_rs, real_symmetric_residual(Vp), real_symmetric_residual(W))
        w_pos = max(w_pos, RDF(_sage_const_0 ) if min([W[i, j].real() for i in range(O.d)
                                          for j in range(O.d)]) > _sage_const_0  else RDF(_sage_const_1 ))
        # (6) F^{(+)} 上で W = V^{(+)}
        Pp = P_pm(O, +_sage_const_1 )
        w_WV = max(w_WV, opnorm(W * Pp - Vp * Pp))
        # (7) c_+(M)：W を F^{(+)} の実基底へ制限した対称行列の最大固有値
        Wr = matrix(RDF, [[W[i, j].real() for j in range(O.d)] for i in range(O.d)])
        Wplus = Bplus.transpose() * Wr * Bplus
        cplus = max([RDF(CDF(z).real()) for z in Wplus.eigenvalues()])
        Lhalf = Lambda_half_M(O, P)
        Lhalf2 = Lambda_delta_M(O, P, RDF(_sage_const_1 ) / _sage_const_2 )
        w_cplus = max(w_cplus, abs(cplus - Lhalf) / Lhalf, abs(Lhalf2 - Lhalf) / Lhalf)
        # (8) Λ̌_max の固有ベクトルが F^{(+)} に属すること（εq = q）
        Qmax = Q_check(O, tuple([_sage_const_1 ] * M), ns)
        # Q̌_max の列のうちノルム最大のものを固有ベクトルに取る
        best = None
        for j in range(O.d):
            col = Qmax.column(j)
            if best is None or col.norm() > best.norm():
                best = col
        q = best / best.norm()
        w_evec = max(w_evec, (E * q - q).norm(),
                     (Vp * q - CDF(Lhalf) * q).norm() / Lhalf)

ok_all &= report("(1) Z_j, Y_j はエルミート", w1, TOL)
ok_all &= report("(2) Ž_μ^* = Ž_{M+1−μ}, Y̌_μ^* = Y̌_{M+1−μ}", w2, TOL)
ok_all &= report("(3a) conj(α_μ) = −α_{M+1−μ}", w3a, TOL)
ok_all &= report("(3) (ψ̌_μ^†)^* = ψ̌_{M+1−μ}", w3, TOL)
ok_all &= report("(4a) ň_μ はエルミート", w4, TOL)
ok_all &= report("(4b) Q̌_ε はエルミート", w4q, TOL)
ok_all &= report("(5a) V^{(+)}, W は実対称", w_rs, TOL)
print(f"  (5b) W の成分がすべて正: {'PASS' if w_pos == _sage_const_0  else 'FAIL'}")
ok_all &= (w_pos == _sage_const_0 )
ok_all &= report("(6) W P^{(+)} = V^{(+)} P^{(+)}", w_WV, TOL)
ok_all &= report("(7) c_+(M) = Λ^{(1/2)}_M（F^{(+)} 上の最大 Rayleigh 商）", w_cplus, TOL)
ok_all &= report("(8) 最大固有ベクトル q: εq = q かつ V^{(+)}q = Λ^{(1/2)}_M q", w_evec, TOL)

print("=== check_04: " + ("ALL PASS" if ok_all else "FAIL") + " ===")

